//! The router mediates git and GitHub traffic for an isolated agent task.
//!
//! Issues #261, #262, #263: an agent that reaches GitHub only through the
//! router should neither hold a credential nor be able to destroy history, and
//! a router on an internal network should be reachable by clients that refuse
//! plaintext. These drive the released binary so the whole path is exercised.

fn free_port() -> u16 {
    // `bind(":0")` then drop releases the port before the child binds it, so
    // another test binary running concurrently can take it in that window.
    // The loser then sends its requests to the winner's router, which answers
    // with its own tokens -- seen on CI as a scoped token appearing
    // unrestricted, because the reply came from a router that had never heard
    // of the scope (issue #368).
    //
    // The OS still picks the port, since only it knows what is already in use.
    // What is added is that no port is handed out twice within this process,
    // which removes the collisions between the suites of one binary; a caller
    // that still loses to another binary retries (see `Router::start`).
    use std::sync::{Mutex, OnceLock};
    static HANDED_OUT: OnceLock<Mutex<std::collections::HashSet<u16>>> = OnceLock::new();
    let seen = HANDED_OUT.get_or_init(|| Mutex::new(std::collections::HashSet::new()));
    for _ in 0..4_000 {
        let port = TcpListener::bind("127.0.0.1:0")
            .expect("bind ephemeral")
            .local_addr()
            .expect("address")
            .port();
        if seen.lock().expect("port registry").insert(port) {
            return port;
        }
    }
    panic!("no unused ephemeral port")
}

/// An upstream that accepts every push, so a refusal can only come from the
/// router rather than from GitHub.
///
/// A `/compare/` request is answered as a fast-forward, because every push to
/// an existing ref now asks the upstream whether it is one (issue #272); an
/// upstream that could not answer would refuse the push and these tests would
/// be measuring the wrong refusal.

fn permissive_git_upstream() -> u16 {
    upstream_comparing("ahead")
}

fn upstream_comparing(status: &'static str) -> u16 {
    let listener = TcpListener::bind("127.0.0.1:0").expect("bind upstream");
    let port = listener.local_addr().expect("address").port();
    std::thread::spawn(move || {
        for stream in listener.incoming() {
            let Ok(mut stream) = stream else { continue };
            let mut scratch = [0; 8192];
            let read = stream.read(&mut scratch).unwrap_or(0);
            let request = String::from_utf8_lossy(&scratch[..read]).to_string();
            if request.contains("/compare/") {
                let body = format!("{{\"status\":\"{status}\"}}");
                let _ = stream.write_all(
                    format!(
                        "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\n\
                         content-length: {}\r\nconnection: close\r\n\r\n{body}",
                        body.len()
                    )
                    .as_bytes(),
                );
                continue;
            }
            let body = "0031\x01000eunpack ok\n0019ok refs/heads/main\n00000000";
            let _ = stream.write_all(
                format!(
                    "HTTP/1.1 200 OK\r\ncontent-type: application/x-git-receive-pack-result\r\n\
                     content-length: {}\r\nconnection: close\r\n\r\n{body}",
                    body.len()
                )
                .as_bytes(),
            );
        }
    });
    port
}

struct Router {
    child: Child,
    port: u16,
    data: tempfile::TempDir,
}

impl Drop for Router {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

impl Router {
    /// Start a router, retrying if a sibling test binary won the port.
    ///
    /// Losing the race is recoverable -- the next port will be a different
    /// one -- so it is retried rather than failing the test (issue #368).
    fn start(upstream: u16) -> Self {
        for _ in 0..10 {
            if let Some(router) = Self::try_start(upstream) {
                return router;
            }
        }
        panic!("could not claim a port for the router in ten attempts");
    }

    fn try_start(upstream: u16) -> Option<Self> {
        let data = tempfile::tempdir().expect("data dir");
        let port = free_port();
        let child = Command::new(env!("CARGO_BIN_EXE_link-assistant-router"))
            .arg("serve")
            .env("TOKEN_SECRET", "agent-sandbox-secret")
            .env("ROUTER_HOST", "127.0.0.1")
            .env("ROUTER_PORT", port.to_string())
            .env("STORAGE_POLICY", "text")
            .env("DATA_DIR", data.path())
            .env("DISABLE_LOGIN_API", "true")
            .env("GITHUB_PROXY_TOKEN", "operator-secret")
            .env(
                "GITHUB_PROXY_BASE_URL",
                format!("http://127.0.0.1:{upstream}"),
            )
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
            .expect("start the router");
        let mut router = Self { child, port, data };
        let deadline = Instant::now() + Duration::from_secs(40);
        while Instant::now() < deadline {
            // A router answering here is not necessarily *this* router: if a
            // sibling test binary took the port in the window between
            // `free_port` releasing it and the child binding it, the reply
            // comes from that one. Its health endpoint answers 200 just the
            // same, and the mismatch only surfaces later as a token the other
            // router never issued (issue #368). A child that lost the race
            // exits, so its liveness is what distinguishes the two.
            match router.child.try_wait() {
                // Lost the race: the port went to somebody else and this child
                // could not bind it. Recoverable -- the caller tries again.
                Ok(Some(_)) => return None,
                Ok(None) => {}
                Err(error) => panic!("cannot poll the router: {error}"),
            }
            if router.get("/api/health").contains(" 200 ") {
                return Some(router);
            }
            std::thread::sleep(Duration::from_millis(150));
        }
        panic!("router never became healthy on port {}", router.port);
    }

    fn get(&self, path: &str) -> String {
        self.send(&format!(
            "GET {path} HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n"
        ))
    }

    fn send(&self, request: &str) -> String {
        let Ok(mut stream) = TcpStream::connect(("127.0.0.1", self.port)) else {
            return String::new();
        };
        if stream.write_all(request.as_bytes()).is_err() {
            return String::new();
        }
        let mut response = String::new();
        let _ = stream.read_to_string(&mut response);
        response
    }

    fn token(&self, extra: &[&str]) -> String {
        let mut command = Command::new(env!("CARGO_BIN_EXE_link-assistant-router"));
        command
            .args(["tokens", "issue", "--ttl-hours", "1", "--label", "agent"])
            .args(extra)
            .env("TOKEN_SECRET", "agent-sandbox-secret")
            .env("DATA_DIR", self.data.path())
            .env("STORAGE_POLICY", "text");
        String::from_utf8_lossy(&command.output().expect("issue a token").stdout)
            .lines()
            .last()
            .unwrap_or_default()
            .trim()
            .to_string()
    }

    /// Send a `git-receive-pack` push carrying one ref command.
    fn push(&self, token: &str, repository: &str, command: &str) -> String {
        let line = format!("{command}\n");
        let body = format!("{:04x}{line}0000PACK", line.len() + 4);
        self.send(&format!(
            "POST /api/services/github/git/{repository}.git/git-receive-pack HTTP/1.1\r\nHost: x\r\n\
             authorization: Bearer {token}\r\n\
             content-type: application/x-git-receive-pack-request\r\n\
             content-length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        ))
    }
}

/// A real `git push --force` is refused, using the capabilities git actually
/// sends.
///
/// The test below this one passes `force-ref-updates`, which git never sends —
/// it is a JGit/Gerrit *server* capability. That made the guard look effective
/// while a genuine rewrite, announcing only the report-status/side-band family,
/// was forwarded to GitHub and applied (issue #272). This is that exact body,
/// captured from `GIT_TRACE_PACKET` on git 2.43.

#[test]
fn a_real_force_push_is_refused_over_the_git_transport() {
    // The upstream reports the comparison as diverged, which is what GitHub
    // answers for a rewrite that drops commits or an unrelated history.
    let router = Router::start(upstream_comparing("diverged"));
    let token = router.token(&[]);

    let response = router.push(
        &token,
        "acme/demo",
        &format!(
            "{OLD} {NEW} refs/heads/main\0report-status-v2 side-band-64k quiet \
             object-format=sha1 agent=git/2.43.0"
        ),
    );

    assert!(response.contains(" 403 "), "{response}");
    assert!(
        response.contains("x-link-assistant-policy: blocked"),
        "{response}"
    );
}

/// An upstream that cannot answer the comparison refuses the push.
///
/// The credential could be revoked or the API rate-limited. A control an agent
/// is not supposed to talk past must not open when the check cannot run.

#[test]
fn a_push_is_refused_when_the_comparison_cannot_be_made() {
    // Port 1 answers nothing, standing in for an unreachable API.
    let router = Router::start(1);
    let token = router.token(&[]);

    let response = router.push(
        &token,
        "acme/demo",
        &format!("{OLD} {NEW} refs/heads/main\0report-status"),
    );

    assert!(
        response.contains(" 403 "),
        "an unanswerable comparison must not let a possible rewrite through: {response}"
    );
}

#[test]
fn a_force_push_is_refused_over_the_git_transport() {
    let router = Router::start(permissive_git_upstream());
    let token = router.token(&[]);

    let response = router.push(
        &token,
        "acme/demo",
        &format!("{OLD} {NEW} refs/heads/main\0report-status force-ref-updates"),
    );

    assert!(response.contains(" 403 "), "{response}");
    assert!(
        response.contains("force-updating refs/heads/main"),
        "{response}"
    );
    assert!(
        response.contains("x-link-assistant-policy: blocked"),
        "{response}"
    );
}

#[test]
fn a_branch_deletion_is_refused_over_the_git_transport() {
    let router = Router::start(permissive_git_upstream());
    let token = router.token(&[]);

    let response = router.push(
        &token,
        "acme/demo",
        &format!("{OLD} {ZERO} refs/heads/main"),
    );

    assert!(response.contains(" 403 "), "{response}");
    assert!(response.contains("deleting refs/heads/main"), "{response}");
}

#[test]
fn an_ordinary_push_reaches_the_upstream() {
    let router = Router::start(permissive_git_upstream());
    let token = router.token(&[]);

    let response = router.push(
        &token,
        "acme/demo",
        &format!("{OLD} {NEW} refs/heads/feature\0report-status"),
    );

    assert!(response.contains(" 200 "), "{response}");
    assert!(response.contains("unpack ok"), "{response}");
}

#[test]
fn a_scoped_token_cannot_push_to_another_repository() {
    let router = Router::start(permissive_git_upstream());
    let token = router.token(&["--github-repo", "acme/demo"]);

    let allowed = router.push(
        &token,
        "acme/demo",
        &format!("{OLD} {NEW} refs/heads/feature\0report-status"),
    );
    assert!(allowed.contains(" 200 "), "its own repository: {allowed}");

    let refused = router.push(
        &token,
        "someone-else/private",
        &format!("{OLD} {NEW} refs/heads/feature\0report-status"),
    );
    assert!(refused.contains(" 403 "), "another repository: {refused}");
    assert!(
        refused.contains("outside this token's repositories"),
        "{refused}"
    );
}

#[test]
fn a_scoped_token_cannot_reach_another_repository_over_rest() {
    let router = Router::start(permissive_git_upstream());
    let token = router.token(&["--github-repo", "acme/demo"]);

    let response = router.send(&format!(
        "GET /api/services/github/api/v3/repos/someone-else/private/issues HTTP/1.1\r\nHost: x\r\n\
         authorization: Bearer {token}\r\nConnection: close\r\n\r\n"
    ));

    assert!(response.contains(" 403 "), "{response}");
    assert!(
        response.contains("x-link-assistant-policy: blocked"),
        "{response}"
    );
}

#[test]
fn an_unrestricted_token_is_not_narrowed() {
    let router = Router::start(permissive_git_upstream());
    let token = router.token(&[]);

    let response = router.push(
        &token,
        "anyone/anything",
        &format!("{OLD} {NEW} refs/heads/feature\0report-status"),
    );

    assert!(response.contains(" 200 "), "{response}");
}
